#include "ud/operator.h"
#include "../../foundation/internal.h"
/* The operator declaration is queried by direct C binding and by the component
 * descriptor. Runtime field/type proofs add no second configuration grammar. */
ud_status ud_operator_configuration_schema(int32_t kind, ud_string *out) {
    if (!out) return UD_INVALID;
    const char *schema = NULL;
    switch (kind) {
    case UD_OPERATOR_SORT: schema = "{\"type\":\"object\",\"properties\":{\"keys\":{\"type\":\"array\",\"items\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"minItems\":1,\"maxItems\":16,\"uniqueItems\":true},\"descending\":{\"type\":\"boolean\"},\"partitions\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":64}},\"required\":[\"keys\"],\"additionalProperties\":false}"; break;
    case UD_OPERATOR_AGGREGATE: schema = "{\"type\":\"object\",\"properties\":{\"plan\":{\"type\":\"object\"},\"partitions\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":64}},\"required\":[\"plan\"],\"additionalProperties\":false}"; break;
    case UD_OPERATOR_JOIN: schema = "{\"type\":\"object\",\"properties\":{\"leftKeys\":{\"type\":\"array\",\"items\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"minItems\":1,\"maxItems\":16,\"uniqueItems\":true},\"rightKeys\":{\"type\":\"array\",\"items\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"minItems\":1,\"maxItems\":16,\"uniqueItems\":true},\"joinType\":{\"type\":\"string\",\"enum\":[\"inner\",\"left\",\"right\",\"full\",\"semi\",\"anti\"],\"default\":\"inner\"},\"rightAliases\":{\"type\":\"object\",\"additionalProperties\":{\"type\":\"string\",\"minLength\":1}},\"strategy\":{\"type\":\"string\",\"enum\":[\"auto\",\"hash\",\"graceHash\",\"merge\"],\"default\":\"auto\"},\"partitions\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":64}},\"required\":[\"leftKeys\",\"rightKeys\"],\"additionalProperties\":false}"; break;
    case UD_OPERATOR_WINDOW: schema = "{\"type\":\"object\",\"properties\":{\"keys\":{\"type\":\"array\",\"items\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"minItems\":1,\"maxItems\":16,\"uniqueItems\":true},\"partitionKeys\":{\"type\":\"integer\",\"minimum\":0},\"function\":{\"type\":\"string\",\"enum\":[\"rowNumber\",\"rank\",\"denseRank\",\"lag\",\"lead\",\"first\",\"last\",\"runningSum\",\"movingSum\",\"movingAverage\"]},\"name\":{\"type\":\"string\",\"minLength\":1},\"column\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"offset\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":65536,\"default\":1},\"frame\":{\"type\":\"object\",\"properties\":{\"type\":{\"type\":\"string\",\"enum\":[\"rows\",\"range\"],\"default\":\"rows\"},\"preceding\":{\"type\":\"integer\",\"minimum\":0},\"following\":{\"type\":\"integer\",\"minimum\":0}},\"required\":[\"preceding\",\"following\"],\"additionalProperties\":false},\"averageRounding\":{\"type\":\"string\",\"enum\":[\"exact\",\"halfEven\"],\"default\":\"halfEven\"}},\"required\":[\"keys\",\"partitionKeys\",\"function\",\"name\"],\"additionalProperties\":false}"; break;
    case UD_OPERATOR_MERGE: schema = "{\"type\":\"object\",\"properties\":{\"keys\":{\"type\":\"array\",\"items\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"minItems\":1,\"maxItems\":16,\"uniqueItems\":true}},\"required\":[\"keys\"],\"additionalProperties\":false}"; break;
    case UD_OPERATOR_MERGE_JOIN: schema = "{\"type\":\"object\",\"properties\":{\"leftKeys\":{\"type\":\"array\",\"items\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"minItems\":1,\"maxItems\":16,\"uniqueItems\":true},\"rightKeys\":{\"type\":\"array\",\"items\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"minItems\":1,\"maxItems\":16,\"uniqueItems\":true},\"joinType\":{\"type\":\"string\",\"enum\":[\"inner\",\"left\",\"right\",\"full\",\"semi\",\"anti\"],\"default\":\"inner\"},\"rightAliases\":{\"type\":\"object\",\"additionalProperties\":{\"type\":\"string\",\"minLength\":1}},\"strategy\":{\"type\":\"string\",\"enum\":[\"auto\",\"hash\",\"graceHash\",\"merge\"],\"default\":\"auto\"},\"partitions\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":64}},\"required\":[\"leftKeys\",\"rightKeys\"],\"additionalProperties\":false}"; break;
    case UD_OPERATOR_PIVOT: schema = "{\"type\":\"object\",\"properties\":{\"setKeys\":{\"type\":\"array\",\"items\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"minItems\":1,\"maxItems\":16,\"uniqueItems\":true},\"pivotKey\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"valueColumn\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"values\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":4096,\"items\":{\"type\":\"object\",\"properties\":{\"value\":{},\"name\":{\"type\":\"string\",\"minLength\":1}},\"required\":[\"value\",\"name\"],\"additionalProperties\":false}},\"errorPolicy\":{\"type\":\"string\",\"enum\":[\"fail\",\"redirect\",\"ignore\"],\"default\":\"fail\"},\"includeInput\":{\"type\":\"boolean\",\"default\":false},\"duplicate\":{\"type\":\"string\",\"enum\":[\"reject\",\"first\",\"last\",\"sum\",\"count\",\"min\",\"max\"],\"default\":\"reject\"}},\"required\":[\"setKeys\",\"pivotKey\",\"valueColumn\",\"values\"],\"additionalProperties\":false}"; break;
    case UD_OPERATOR_UNPIVOT: schema = "{\"type\":\"object\",\"properties\":{\"columns\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":65536,\"items\":{\"type\":\"object\",\"required\":[\"column\",\"key\"],\"properties\":{\"column\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}]},\"key\":{\"type\":\"string\",\"minLength\":1}},\"additionalProperties\":false}},\"retain\":{\"type\":\"array\",\"items\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"uniqueItems\":true},\"keyName\":{\"type\":\"string\",\"minLength\":1},\"valueName\":{\"type\":\"string\",\"minLength\":1},\"nulls\":{\"type\":\"string\",\"enum\":[\"include\",\"skip\"],\"default\":\"include\"}},\"required\":[\"columns\",\"keyName\",\"valueName\"],\"additionalProperties\":false}"; break;
    case UD_OPERATOR_ROW_SAMPLING: schema = "{\"type\":\"object\",\"properties\":{\"count\":{\"type\":\"integer\",\"minimum\":0},\"seed\":{\"type\":\"integer\",\"minimum\":0},\"whenShort\":{\"type\":\"string\",\"enum\":[\"all\",\"fail\"],\"default\":\"all\"}},\"required\":[\"count\",\"seed\"],\"additionalProperties\":false}"; break;
    case UD_OPERATOR_PERCENTAGE_SAMPLING: schema = "{\"type\":\"object\",\"properties\":{\"percentage\":{\"type\":\"number\",\"minimum\":0,\"maximum\":100},\"seed\":{\"type\":\"integer\",\"minimum\":0}},\"required\":[\"percentage\",\"seed\"],\"additionalProperties\":false}"; break;
    case UD_OPERATOR_SCD: schema = "{\"type\":\"object\",\"properties\":{\"cache\":{\"type\":\"string\",\"x-role\":\"cache-resource\"},\"businessKeys\":{\"type\":\"array\",\"items\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"minItems\":1,\"maxItems\":16,\"uniqueItems\":true},\"mapping\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"source\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"target\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"change\":{\"type\":\"string\",\"enum\":[\"key\",\"type1\",\"type2\",\"fixed\"]}},\"required\":[\"source\",\"target\",\"change\"],\"additionalProperties\":false}},\"current\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"validFrom\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"validTo\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"version\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"effectiveTime\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"errorPolicy\":{\"type\":\"string\",\"enum\":[\"fail\",\"redirect\",\"ignore\"],\"default\":\"fail\"},\"includeInput\":{\"type\":\"boolean\"},\"lateEvents\":{\"type\":\"string\",\"enum\":[\"reject\",\"recompute\"],\"default\":\"reject\"},\"surrogate\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"dimensionKeys\":{\"type\":\"array\",\"items\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}],\"x-role\":\"field-selector\"},\"minItems\":1,\"maxItems\":16,\"uniqueItems\":true},\"surrogateSource\":{\"anyOf\":[{\"type\":\"integer\",\"minimum\":0},{\"type\":\"string\",\"minLength\":1}]}},\"required\":[\"cache\",\"businessKeys\",\"dimensionKeys\",\"mapping\",\"current\",\"validFrom\",\"validTo\",\"surrogate\",\"effectiveTime\"],\"additionalProperties\":false}"; break;
    default: return UD_UNSUPPORTED;
    }
    *out = (ud_string){schema, (uint32_t)strlen(schema)};
    return UD_OK;
}
